#include <vector>
#include <cmath>

using namespace std;

class Solution {
public:
    vector<int> pathInZigZagTree(int label) {
        vector<int> path;
        int level = log2(label);
        while (label > 0) {
            path.insert(path.begin(), label);
            int total = pow(2, level) + pow(2, level + 1) - 1;
            label = (total - label) / 2;
            level--;
        }
        return path;
    }
};
